import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../App.css";
import API_BASE_URL from "../config";

const Cart = () => {
  const userId = sessionStorage.getItem("userId");
  const [cartItems, setCartItems] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/cart/user/${userId}`)
      .then((res) => res.json())
      .then((data) => setCartItems(data))
      .catch((err) => console.error("Error loading cart:", err));
  }, [userId]);

  const subtotal = cartItems.reduce((sum, item) => sum + parseFloat(item.price), 0);

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="cart-container">
        <div className="cart-left">
          <h2>My Cart</h2>
          {cartItems.length === 0 ? (
            <p>No items in cart.</p>
          ) : (
            cartItems.map((item, idx) => (
              <div key={idx} className="cart-item">
                <img src={item.image} alt={item.title} className="cart-thumb" />
                <div className="cart-details">
                  <p className="cart-title">{item.title}</p>
                  <p>${parseFloat(item.price).toFixed(2)}</p>
                  <p>{item.description}</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="cart-summary">
          <h3>Order Summary</h3>
          <p><strong>Subtotal:</strong> ${subtotal.toFixed(2)}</p>
          <p><strong>Delivery:</strong> FREE</p>
          <p><strong>Total:</strong> ${subtotal.toFixed(2)}</p>

          <button
  className="checkout-btn"
  onClick={() =>
    navigate("/checkout", {
      state: {
        cartItems,
        subtotal,
      },
    })
  }
>
  Checkout
</button>


          <button className="gpay-btn">G Pay</button>
          <p className="secure-text">🔒 Secure Checkout</p>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default Cart;
